def state(p):
 d={'exists':p.exists()}
 for f in ['exit-code.txt','failure.txt']:
  if (p/f).exists():d[f]=(p/f).read_text()[-1200:]
 if (p/'process.json').exists():
  d['process']=json.loads((p/'process.json').read_text());q=pathlib.Path('/proc')/str(d['process']['pid'])/'cmdline';d['cmdline']=q.read_bytes().decode(errors='replace') if q.exists() else None
 return d
def deploy(n,v):
 p=b/n
 if not p.exists():
  source=zlib.decompress(base64.b64decode(v['payload']));assert hashlib.sha256(source).hexdigest()==v['sha256'];compile(source,str(p/'worker.py'),'exec')
  try:p.mkdir()
  except FileExistsError:pass
  else:
   (p/'worker.py').write_bytes(source)
   with (p/'worker.log').open('xb') as f:proc=subprocess.Popen(['python3',str(p/'worker.py')],stdin=subprocess.DEVNULL,stdout=f,stderr=f,start_new_session=True)
   (p/'process.json').write_text(json.dumps(dict(pid=proc.pid,started_unix=time.time()),indent=2)+'\n')
 assert hashlib.sha256((p/'worker.py').read_bytes()).hexdigest()==v['sha256'],'An existing artifact has a different worker; inspect'
 d=state(p);print(json.dumps({n:d}),flush=True);return d
